1596a','usuario_tipo|994dc0b16f214444ced5d51995ab7e09','vinculo_status|af6736be5e7531bc60aedb36d01dc2f9','workflow_status|8429e67ba20e36b07eb0d656fd3af8a0']) AS x
),
prod_tabelas AS MATERIALIZED (
  SELECT c.relname AS tabela
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind = 'r'
),
prod_colunas AS MATERIALIZED (
  SELECT c.table_name AS tabela,
         md5(string_agg(c.column_name, ',' ORDER BY c.column_name)) AS impressao,
         string_agg(c.column_name, ', ' ORDER BY c.column_name) AS lista
  FROM information_schema.columns c
  JOIN pg_class pc ON pc.relname = c.table_name AND pc.relkind = 'r'
  JOIN pg_namespace pn ON pn.oid = pc.relnamespace AND pn.nspname = 'public'
  WHERE c.table_schema = 'public'
  GROUP BY c.table_name
),
prod_enums AS MATERIALIZED (
  SELECT t.typname AS tipo,
         md5(string_agg(e.enumlabel, ',' ORDER BY e.enumlabel)) AS impressao,
         string_agg(e.enumlabel, ', ' ORDER BY e.enumlabel) AS lista
  FROM pg_type t
  JOIN pg_namespace n ON n.oid = t.typnamespace AND n.nspname = 'public'
  JOIN pg_enum e ON e.enumtypid = t.oid
  WHERE t.typtype = 'e'
  GROUP BY t.typname
)

SELECT 'tabela' AS tipo, r.tabela AS objeto, 'só no repositório' AS situacao,
       'falta aplicar na produção' AS detalhe
FROM repo_tabelas r
WHERE NOT EXISTS (SELECT 1 FROM prod_tabelas p WHERE p.tabela = r.tabela)

UNION ALL
SELECT 'tabela', p.tabela, 'só na produção',
       'criada fora das migrations; trazer para o repositório com IF NOT EXISTS'
FROM prod_tabelas p
WHERE NOT EXISTS (SELECT 1 FROM repo_tabelas r WHERE r.tabela = p.tabela)

UNION ALL
SELECT 'colunas', r.tabela, 'difere',
       'produção tem: ' || left(p.lista, 400)
FROM repo_colunas r JOIN prod_colunas p ON p.tabela = r.tabela
WHERE p.impressao <> r.impressao

UNION ALL
SELECT 'enum', r.tipo, 'difere',
       'produção tem: ' || left(p.lista, 400)
FROM repo_enums r JOIN prod_enums p ON p.tipo = r.tipo
WHERE p.impressao <> r.impressao

UNION ALL
SELECT 'enum', r.tipo, 'só no repositório', 'tipo não existe na produção'
FROM repo_enums r
WHERE NOT EXISTS (SELECT 1 FROM prod_enums p WHERE p.tipo = r.tipo)

UNION ALL
SELECT 'RESUMO', 'estrutura conferida', 'referência',
       (SELECT count(*)::text FROM prod_tabelas) || ' tabelas na produção · '
    || (SELECT count(*)::text FROM repo_tabelas) || ' esperadas pelo repositório'

ORDER BY 1, 3, 2;
